     1	// A synchronous workspace store, independent of whether an editor is visible.
     2	// Notifications run inline after the record is written. Subscribers may detach
     3	// or subscribe while a notification is being delivered.
     4	export function createDraftStore(initial = {}) {
     5	  const records = new Map(Object.entries(initial));
     6	  const listeners = new Set();
     7	  let revision = 0;
     8	  return {
     9	    read(id) { return records.get(id) ?? ""; },
    10	    write(id, text) {
    11	      records.set(id, text);
    12	      const event = { id, text, revision: ++revision };
    13	      for (const listener of [...listeners]) {
    14	        if (listeners.has(listener)) listener(event);
    15	      }
    16	      return event;
    17	    },
    18	    subscribe(listener) {
    19	      listeners.add(listener);
    20	      return () => listeners.delete(listener);
    21	    },
    22	  };
    23	}
